public class Animal {private final String name;public Animal(String name){this.name=name;}protected String name(){return name;}public String voice(){return "Animal "+name;}public boolean equals(Object other){return other!=null&&getClass()==other.getClass()&&name.equals(((Animal)other).name);}public int hashCode(){return java.util.Objects.hash(getClass(),name);}public String toString(){return getClass().getSimpleName()+" "+name;}}
